<script setup lang="ts">
import {onMounted,onBeforeUnmount,watch,ref} from 'vue';
import * as monaco from 'monaco-editor/esm/vs/editor/editor.api.js';
import 'monaco-editor/esm/vs/basic-languages/sql/sql.contribution';
import EditorWorker from 'monaco-editor/esm/vs/editor/editor.worker?worker';
import {format} from 'sql-formatter';
import {api,byteOffset,type Analysis,type Schema} from '../api';
import type {SourceRange} from '../generated/SourceRange';
import type {Completion} from '../generated/Completion';
const props=withDefaults(defineProps<{modelValue:string,id:string,schema:Schema,engine?:string,theme?:string,language?:string}>(),{engine:'sqlite',theme:'light',language:'sql'});
const emit=defineEmits<{ 'update:modelValue':[value:string],run:[all:boolean],diagnostics:[analysis:Analysis]}>();
let decorations:monaco.editor.IEditorDecorationsCollection|undefined;let origin={line:1,column:1,version:0,id:''};
const host=ref<HTMLElement>();let editor:monaco.editor.IStandaloneCodeEditor|undefined;let model:monaco.editor.ITextModel|undefined;const disposables:monaco.IDisposable[]=[];let timer:ReturnType<typeof setTimeout>|undefined;let diagnostics:Analysis={diagnostics:[],ast:[],statements:[]};
(self as typeof self & {MonacoEnvironment: monaco.Environment}).MonacoEnvironment={getWorker:()=>new EditorWorker()};
async function analyze(){if(!model||props.language!=='sql')return;const current=model;const version=current.getVersionId();try{const r=await api<Analysis>('analyze',{sql:current.getValue(),engine:props.engine,schema:props.schema});if(current.isDisposed()||current.getVersionId()!==version)return;diagnostics=r;monaco.editor.setModelMarkers(current,'sql-killer',r.diagnostics.map(d=>({message:d.message,severity:d.severity==='error'?monaco.MarkerSeverity.Error:monaco.MarkerSeverity.Warning,startLineNumber:d.range.line,startColumn:d.range.column,endLineNumber:d.range.end_line,endColumn:d.range.end_column,source:d.category})));emit('diagnostics',r);}catch{/* live analysis does not interrupt typing */}}
function createModel(){decorations?.clear();const uri=monaco.Uri.parse(`inmemory://sql-killer/${encodeURIComponent(props.id)}.${props.language}`);model=monaco.editor.getModel(uri)??monaco.editor.createModel(props.modelValue,props.language,uri);if(model.getValue()!==props.modelValue)model.setValue(props.modelValue);editor?.setModel(model);void analyze();}
onMounted(()=>{editor=monaco.editor.create(host.value!,{automaticLayout:true,fontFamily:'Cascadia Code, Consolas, Microsoft YaHei, monospace',fontSize:14,lineHeight:24,minimap:{enabled:false},padding:{top:18,bottom:16},scrollBeyondLastLine:false,roundedSelection:true,wordWrap:'on',tabSize:2,theme:props.theme==='dark'?'vs-dark':'vs',fixedOverflowWidgets:true});createModel();decorations=editor.createDecorationsCollection();
 disposables.push(editor.onDidChangeModelContent(()=>{decorations?.clear();emit('update:modelValue',editor!.getValue());clearTimeout(timer);timer=setTimeout(()=>void analyze(),450);}));
 editor.addCommand(monaco.KeyMod.CtrlCmd|monaco.KeyCode.Enter,()=>emit('run',false));editor.addCommand(monaco.KeyMod.CtrlCmd|monaco.KeyMod.Shift|monaco.KeyCode.Enter,()=>emit('run',true));
 disposables.push(monaco.languages.registerCompletionItemProvider('sql',{triggerCharacters:['.',' '],provideCompletionItems:async(m,p)=>{if(m!==model)return{suggestions:[]};const word=m.getWordUntilPosition(p);const list=await api<Completion[]>('complete',{sql:m.getValue(),cursor:byteOffset(m.getValue(),m.getOffsetAt(p)),schema:props.schema});const kinds:Record<string,monaco.languages.CompletionItemKind>={column:monaco.languages.CompletionItemKind.Field,table:monaco.languages.CompletionItemKind.Class,function:monaco.languages.CompletionItemKind.Function,keyword:monaco.languages.CompletionItemKind.Keyword,snippet:monaco.languages.CompletionItemKind.Snippet};return{suggestions:list.map(c=>({label:c.label,insertText:c.insert_text,detail:c.detail,kind:kinds[c.kind]??monaco.languages.CompletionItemKind.Text,range:new monaco.Range(p.lineNumber,word.startColumn,p.lineNumber,word.endColumn)}))};}}));
 disposables.push(monaco.languages.registerDocumentFormattingEditProvider('sql',{provideDocumentFormattingEdits:m=>{if(m!==model)return[];try{return[{range:m.getFullModelRange(),text:format(m.getValue(),{language:props.engine==='mysql'?'mysql':'sqlite',keywordCase:'upper'})}]}catch{return[]}}}));
 disposables.push(monaco.languages.registerHoverProvider('sql',{provideHover:(m,p)=>{if(m!==model)return;const word=m.getWordAtPosition(p)?.word;const cols=props.schema.relations.flatMap(r=>r.columns.filter(c=>c.name===word).map(c=>`${r.name}.${c.name} · ${c.data_type} · ${c.primary_key?'主键':c.nullable?'可空':'NOT NULL'}`));if(cols.length)return{contents:cols.map(value=>({value}))};}}));
 disposables.push(monaco.languages.registerCodeActionProvider('sql',{provideCodeActions:(m,range)=>{if(m!==model)return{actions:[],dispose(){}};return{actions:diagnostics.diagnostics.filter(d=>d.replacement&&d.range.line>=range.startLineNumber&&d.range.line<=range.endLineNumber).map(d=>({title:`替换为 ${d.replacement}`,kind:'quickfix',edit:{edits:[{resource:m.uri,versionId:m.getVersionId(),textEdit:{range:new monaco.Range(d.range.line,d.range.column,d.range.end_line,d.range.end_column),text:d.replacement!}}]}})),dispose(){}};}}));
});
watch(()=>props.id,createModel);watch(()=>props.modelValue,v=>{if(model&&model.getValue()!==v)model.setValue(v)});watch(()=>props.schema,()=>void analyze(),{deep:true});watch(()=>props.theme,t=>monaco.editor.setTheme(t==='dark'?'vs-dark':'vs'));
onBeforeUnmount(()=>{clearTimeout(timer);disposables.forEach(d=>d.dispose());editor?.dispose();});
async function source(all=false):Promise<string>{if(!editor||!model)return props.modelValue;const selection=editor.getSelection();origin={line:1,column:1,version:model.getVersionId(),id:props.id};if(!all&&selection&&!selection.isEmpty()){origin.line=selection.startLineNumber;origin.column=selection.startColumn;return model.getValueInRange(selection);}if(all)return model.getValue();const r=await api<{sql:string,range:SourceRange}|null>('statement',{sql:model.getValue(),cursor:byteOffset(model.getValue(),model.getOffsetAt(editor.getPosition()!))});if(r){origin.line=r.range.line;origin.column=r.range.column;}return r?.sql??model.getValue();}
function highlight(range:SourceRange|null){if(!editor||!model||!range||origin.id!==props.id||origin.version!==model.getVersionId()){decorations?.clear();return;}const line=(n:number)=>origin.line+n-1;const col=(n:number,c:number)=>c+(n===1?origin.column-1:0);decorations?.set([{range:new monaco.Range(line(range.line),col(range.line,range.column),line(range.end_line),col(range.end_line,range.end_column)),options:{className:'sql-motion-highlight',inlineClassName:'sql-motion-text',overviewRuler:{color:'#3b82f6',position:monaco.editor.OverviewRulerLane.Full}}}]);}

function insert(text:string){editor?.executeEdits('insert',[{range:editor.getSelection()!,text,forceMoveMarkers:true}]);editor?.focus();}
defineExpose({source,insert,highlight,format:()=>editor?.getAction('editor.action.formatDocument')?.run(),focus:()=>editor?.focus()});
</script>
<template><div ref="host" class="sql-editor" :data-editor="id" /></template>
